import{_ as o,c as e,o as r,aj as l}from"./chunks/framework.VtnL2jmu.js";const u=JSON.parse('{"title":"9Router 配置 Google OIDC 单点登录（SSO）","description":"","frontmatter":{},"headers":[],"relativePath":"tool/9Router配置GoogleOIDC 单点登录.md","filePath":"tool/9Router配置GoogleOIDC 单点登录.md"}'),n={name:"tool/9Router配置GoogleOIDC 单点登录.md"};function s(i,t,a,d,g,c){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="_9router-配置-google-oidc-单点登录-sso" tabindex="-1">9Router 配置 Google OIDC 单点登录（SSO） <a class="header-anchor" href="#_9router-配置-google-oidc-单点登录-sso" aria-label="Permalink to “9Router 配置 Google OIDC 单点登录（SSO）”">​</a></h1><h2 id="_1-配置目标" tabindex="-1">1. 配置目标 <a class="header-anchor" href="#_1-配置目标" aria-label="Permalink to “1. 配置目标”">​</a></h2><p>为 9Router 仪表盘启用 Google OIDC 单点登录，用户可通过 Google 账号登录后台，同时保留 API 密钥用于模型调用。</p><hr><h2 id="_2-google-cloud-console-配置" tabindex="-1">2. Google Cloud Console 配置 <a class="header-anchor" href="#_2-google-cloud-console-配置" aria-label="Permalink to “2. Google Cloud Console 配置”">​</a></h2><p><strong>2.1 进入控制台</strong></p><ul><li>访问 <a href="https://console.cloud.google.com/" target="_blank" rel="noreferrer">Google Cloud Console</a></li><li>登录 Google 账号</li></ul><p><strong>2.2 创建/选择项目</strong></p><ul><li>点击顶部项目下拉菜单 → “新建项目”</li><li>命名项目（如 <code>9router-dashboard</code>）→ 点击“创建”</li><li>确保当前操作在该项目下进行</li></ul><p><strong>2.3 配置 OAuth 同意屏幕</strong></p><ul><li>左侧菜单：<strong>APIs &amp; Services</strong> → <strong>OAuth consent screen</strong></li><li>User Type：选择 <strong>External</strong> → 点击“创建”</li><li>填写必填项： <ul><li><strong>App name</strong>：应用名称（显示给用户）</li><li><strong>User support email</strong>：用户支持邮箱</li><li><strong>Developer contact information</strong>：开发者联系邮箱</li></ul></li><li>Scopes 步骤：保持默认的 <code>openid</code>、<code>profile</code>、<code>email</code> → 保存并继续</li></ul><p><strong>2.4 生成 OAuth 客户端 ID</strong></p><ul><li>左侧菜单：<strong>APIs &amp; Services</strong> → <strong>Credentials</strong></li><li>点击 <strong>+ CREATE CREDENTIALS</strong> → <strong>OAuth client ID</strong></li><li>配置项： <ul><li><strong>Application type</strong>：Web application</li><li><strong>Name</strong>：客户端名称（如 <code>9router-dashboard-client</code>）</li><li><strong>Authorized JavaScript origins</strong>：<code>https://your-domain.com</code></li><li><strong>Authorized redirect URIs</strong>：<code>https://your-domain.com/api/auth/oidc/callback</code></li></ul></li><li>点击 <strong>Create</strong></li><li><strong>立即复制并保存 Client ID 和 Client Secret</strong>（Secret 不再显示）</li></ul><blockquote><p>⚠️ <strong>重要</strong>：回调地址必须与 9Router 配置界面中的 Redirect URI 完全一致，否则登录失败。</p></blockquote><hr><h2 id="_3-9router-配置界面填写" tabindex="-1">3. 9Router 配置界面填写 <a class="header-anchor" href="#_3-9router-配置界面填写" aria-label="Permalink to “3. 9Router 配置界面填写”">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>填写值</th></tr></thead><tbody><tr><td><strong>Auth Mode</strong></td><td>按需选择（建议先选 <code>Both</code> 测试）</td></tr><tr><td><strong>Issuer URL</strong></td><td><code>https://accounts.google.com</code></td></tr><tr><td><strong>Client ID</strong></td><td>从 Google Cloud Console 复制</td></tr><tr><td><strong>Client Secret</strong></td><td>从 Google Cloud Console 复制</td></tr><tr><td><strong>Scopes</strong></td><td><code>openid profile email</code></td></tr><tr><td><strong>Login Button Label</strong></td><td>自定义（如 <code>Sign in with Google</code>）</td></tr><tr><td><strong>Redirect URI</strong></td><td><code>https://your-domain.com/api/auth/oidc/callback</code>（只读，由系统提供）</td></tr></tbody></table><hr><h2 id="_4-验证与保存" tabindex="-1">4. 验证与保存 <a class="header-anchor" href="#_4-验证与保存" aria-label="Permalink to “4. 验证与保存”">​</a></h2><ul><li>填写完成后，点击 <strong>Test connection</strong></li><li>预期返回：<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Connection OK. Discovery loaded from https://accounts.google.com. Client secret validated too.</span></span></code></pre></div></li><li>测试通过后，点击 <strong>Save auth mode</strong> 保存配置</li></ul><hr><h2 id="_5-多项目复用建议" tabindex="-1">5. 多项目复用建议 <a class="header-anchor" href="#_5-多项目复用建议" aria-label="Permalink to “5. 多项目复用建议”">​</a></h2><ul><li><strong>推荐做法</strong>：在同一个 Google Cloud 项目下，为每个应用<strong>创建新的 OAuth 客户端 ID</strong>，而非共用同一个客户端</li><li>优点：共享 OAuth 同意屏幕配置，用户授权体验统一</li><li>操作为每个新应用重复 <strong>步骤 2.4</strong>，填入各自不同的 Redirect URI</li></ul><hr><h2 id="_6-常见问题排查" tabindex="-1">6. 常见问题排查 <a class="header-anchor" href="#_6-常见问题排查" aria-label="Permalink to “6. 常见问题排查”">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>解决方案</th></tr></thead><tbody><tr><td><strong>Discovery 加载失败</strong></td><td>检查 Issuer URL 是否为 <code>https://accounts.google.com</code>（无多余斜杠）</td></tr><tr><td><strong>Client secret 验证失败</strong></td><td>确认 Client ID 和 Secret 复制正确，无多余空格</td></tr><tr><td><strong>登录后回调失败</strong></td><td>检查 Google 侧 Redirect URI 是否与 9Router 配置<strong>完全一致</strong>（含路径和斜杠）</td></tr><tr><td><strong>配置生效慢</strong></td><td>Google 提示需 5 分钟到几小时，实际通常 1-2 分钟内生效</td></tr></tbody></table><hr><h2 id="_7-安全提示" tabindex="-1">7. 安全提示 <a class="header-anchor" href="#_7-安全提示" aria-label="Permalink to “7. 安全提示”">​</a></h2><ul><li>Client Secret 为敏感信息，<strong>只保存一次</strong>，丢失需重新生成</li><li>生产环境建议使用 <strong>HTTPS</strong> 协议</li><li>测试完成后，可根据需要将 Auth Mode 从 <code>Both</code> 切换为 <code>OIDC only</code>（确保 OIDC 登录正常后再操作）</li></ul>',29)])])}const p=o(n,[["render",s]]);export{u as __pageData,p as default};
